JOIN comum.papel p ON
p.id = pe.id_papel
JOIN comum.usuario u ON
u.id_usuario = pe.id_usuario
LEFT JOIN comum.unidade und ON
und.id_unidade = pe.id_unidade_papel
WHERE pe.autorizada
AND pe.id_unidade_papel = 1932;
